import{_ as e,o,c as d,a3 as r}from"./chunks/framework.D8G7yXPy.js";const i=JSON.parse('{"title":"组件","description":"","frontmatter":{},"headers":[],"relativePath":"reference/components.md","filePath":"reference/components.md"}'),a={name:"reference/components.md"};function c(n,t,p,s,m,l){return o(),d("div",null,[...t[0]||(t[0]=[r('<h1 id="组件" tabindex="-1">组件 <a class="header-anchor" href="#组件" aria-label="Permalink to &quot;组件&quot;">​</a></h1><p>通用组件从 <code>@ray-template/ui</code> 导入，也可用 <code>/table-pro</code>、<code>/barcode</code> 等子路径按需加载。Ray Admin 内可以使用 <code>@/components</code>。路由过渡位于 <code>@ray-template/admin-shell</code>，由应用接入当前路由和缓存状态。许多组件包装 Naive UI：本文列出模板添加、改写或消费的属性、插槽和事件，原始控件的其余能力以锁定依赖的类型为准。</p><table tabindex="0"><thead><tr><th>组件</th><th>Props 类型</th><th>主要用途</th></tr></thead><tbody><tr><td><a href="./table-pro.html">RTablePro</a></td><td><code>TableProProps</code></td><td>纯表格、远端查询、自适应高度、列设置、导出及可选打印</td></tr><tr><td><a href="./components/form.html">RForm</a></td><td><code>FormProps</code></td><td>表单加载、校验、重置和键盘提交</td></tr><tr><td><a href="./components/modal.html">RModal</a></td><td><code>ModalProps</code></td><td>受控弹窗、预设宽度和全屏卡片</td></tr><tr><td><a href="./components/chart.html">RChart</a></td><td><code>ChartProps</code></td><td>ECharts 初始化、主题和导出</td></tr><tr><td><a href="./components/flow.html">RFlow</a></td><td><code>FlowProps</code></td><td>LogicFlow 流程图与只读切换</td></tr><tr><td><a href="./components/collapse-grid.html">RCollapseGrid</a></td><td><code>CollapseGridProps</code></td><td>可折叠筛选区及操作列</td></tr><tr><td><a href="./components/segment.html">RSegment</a></td><td><code>SegmentProps</code></td><td>分段选项、图标和提示</td></tr><tr><td><a href="./components/more-dropdown.html">RMoreDropdown</a></td><td><code>MoreDropdownProps</code></td><td>图标菜单、行操作</td></tr><tr><td><a href="./components/iframe.html">RIframe</a></td><td><code>IframeProps</code></td><td>外部页面与加载状态</td></tr><tr><td><a href="./components/barcode.html">RBarcode</a></td><td><code>BarcodeProps</code></td><td>Canvas / SVG 条码</td></tr><tr><td><a href="./components/draggable-card.html">RDraggableCard</a></td><td><code>DefaultPosition</code>（位置类型）</td><td>可拖动卡片与拖动边界</td></tr><tr><td><a href="./components/route-transition.html">RTransitionComponent</a></td><td><code>TransitionComponentProps</code></td><td>路由过渡与 KeepAlive</td></tr><tr><td><a href="./icons.html#ricon-api">RIcon</a></td><td><code>IconProps</code></td><td>类型化 SVG 雪碧图</td></tr></tbody></table><p><a href="./components/app.html">应用组件与 Provider</a> 使用模板的状态、主题或路由，按文件导入。<a href="./components/qr-code.html">二维码</a> 使用 <code>vue3-next-qrcode</code>，不属于 <code>@/components</code> 的导出。</p><p>组件实现、样式和类型放在同一个组件目录。组件属性对象也有具名导出，例如 <code>formProps</code>、<code>modalProps</code>、<code>chartProps</code>；业务代码通常直接使用组件和公开 Props 类型。<code>TablePro</code> 统一使用组件 ref 获取实例，<code>RForm</code>、<code>RChart</code>、<code>RFlow</code> 使用各自的 <code>onRegister</code> 契约。</p><p><a href="https://github.com/XiaoDaiGua-Ray/ray-template/blob/2c6bd6b499bc1918ef9e9305d6ed78553c0503c7/packages/ui/src/index.ts" target="_blank" rel="noreferrer">公开导出</a> · <a href="https://github.com/XiaoDaiGua-Ray/ray-template/blob/2c6bd6b499bc1918ef9e9305d6ed78553c0503c7/apps/admin/src/components/README.md" target="_blank" rel="noreferrer">组件约定</a> · <a href="https://github.com/XiaoDaiGua-Ray/ray-template/tree/2c6bd6b499bc1918ef9e9305d6ed78553c0503c7/apps/admin/src/views/demo" target="_blank" rel="noreferrer">示例源码</a></p>',6)])])}const f=e(a,[["render",c]]);export{i as __pageData,f as default};
